 ('CopyingAndMoving', 'Copying', 'CopyFile', 'shutil.copy(source, destination)', "shutil.copy copies one file to a destination that is either a folder, which keeps the file's name, or a file name, which becomes the copy's name; an existing destination file is replaced, and the call returns the path of the new file.", ("(lambda g: (exec('import os, shutil, tempfile, zipfile, io\\nfrom pathlib import Path\\nt = Path(tempfile.mkdtemp())\\n(t/\\'a.txt\\').write_text(\\'Hello\\')\\n(t/\\'box\\').mkdir()\\nr1 = shutil.copy(t/\\'a.txt\\', t/\\'box\\')\\nr2 = shutil.copy(t/\\'a.txt\\', t/\\'box\\'/\\'b.txt\\')\\nout = (Path(r1).name, Path(r2).name, sorted(p.name for p in (t/\\'box\\').iterdir()), (t/\\'a.txt\\').exists())\\nshutil.rmtree(t)\\n', g), g['out'])[1])({})", "('a.txt', 'b.txt', ['a.txt', 'b.txt'], True)")),
 ('CopyingAndMoving', 'Copying', 'CopyFolderTree', 'shutil.copytree(source, destination)', 'shutil.copytree copies a whole folder with all its files and subfolders to a new folder that must not exist yet, and returns the destination; it raises FileExistsError when the destination exists.', ("(lambda g: (exec('import os, shutil, tempfile, zipfile, io\\nfrom pathlib import Path\\nt = Path(tempfile.mkdtemp())\\n(t/\\'spam\\'/\\'eggs\\').mkdir(parents=True)\\n(t/\\'spam\\'/\\'file1.txt\\').write_text(\\'Hello\\')\\n(t/\\'spam\\'/\\'eggs\\'/\\'file2.txt\\').write_text(\\'Hi\\')\\nshutil.copytree(t/\\'spam\\', t/\\'spam_backup\\')\\ncopied = sorted(str(p.relative_to(t/\\'spam_backup\\')) for p in (t/\\'spam_backup\\').rglob(\\'*\\'))\\ntry:\\n    shutil.copytree(t/\\'spam\\', t/\\'spam_backup\\')\\n    second = \\'no error\\'\\nexcept FileExistsError:\\n    second = \\'FileExistsError\\'\\nout = (copied, second)\\nshutil.rmtree(t)\\n', g), g['out'])[1])({})", "(['eggs', 'eggs/file2.txt', 'file1.txt'], 'FileExistsError')")),
 ('CopyingAndMoving', 'Copying', 'CopyWithMetadata', 'shutil.copy2(source, destination)', 'shutil.copy2 copies a file like shutil.copy and also tries to keep its metadata, such as the modification time, which shutil.copy does not keep; copytree uses copy2 for every file.', ("(lambda g: exec('import os, shutil, tempfile, zipfile, io\\nfrom pathlib import Path\\nt = Path(tempfile.mkdtemp())\\nsrc = t/\\'a.txt\\'\\nsrc.write_text(\\'x\\')\\nos.utime(src, (n * 100_000_000, n * 100_000_000))\\nshutil.copy(src, t/\\'plain.txt\\')\\nshutil.copy2(src, t/\\'kept.txt\\')\\nout = (int((t/\\'kept.txt\\').stat().st_mtime), (t/\\'plain.txt\\').stat().st_mtime > 1_500_000_000)\\nshutil.rmtree(t)\\n', g) or g['out'])({'n': 10})", '(1000000000, True)')),
 ('CopyingAndMoving', 'Copying', 'ExistingDestination', 'shutil.copytree(source, destination, dirs_exist_ok=True)', 'With dirs_exist_ok=True, copytree continues into a destination folder that already exists and overwrites files of the same name there, leaving the other files in place.', ("(lambda g: (exec('import os, shutil, tempfile, zipfile, io\\nfrom pathlib import Path\\nt = Path(tempfile.mkdtemp())\\n(t/\\'src\\').mkdir()\\n(t/\\'src\\'/\\'a.txt\\').write_text(\\'new\\')\\n(t/\\'dst\\').mkdir()\\n(t/\\'dst\\'/\\'a.txt\\').write_text(\\'old\\')\\n(t/\\'dst\\'/\\'keep.txt\\').write_text(\\'kept\\')\\nshutil.copytree(t/\\'src\\', t/\\'dst\\', dirs_exist_ok=True)\\nout = (sorted(p.name for p in (t/\\'dst\\').iterdir()), (t/\\'dst\\'/\\'a.txt\\').read_text())\\nshutil.rmtree(t)\\n', g), g['out'])[1])({})", "(['a.txt', 'keep.txt'], 'new')")),
 ('CopyingAndMoving', 'Moving', 'MoveFileOrFolder', 'shutil.move(source, destination)', 'shutil.move moves a file or a folder to a destination and returns where it went; if the destination is an existing folder the source goes inside it under its own name, and across file systems the move is a copy followed by a delete.', ("(lambda g: (exec('import os, shutil, tempfile, zipfile, io\\nfrom pathlib import Path\\nt = Path(tempfile.mkdtemp())\\n(t/\\'spam\\').mkdir()\\n(t/\\'spam2\\').mkdir()\\n(t/\\'spam\\'/\\'file1.txt\\').write_text(\\'Hello\\')\\nr = shutil.move(t/\\'spam\\'/\\'file1.txt\\', t/\\'spam2\\')\\nout = (type(r).__name__, Path(r).relative_to(t).as_posix(), (t/\\'spam\\'/\\'file1.txt\\').exists())\\nshutil.rmtree(t)\\n', g), g['out'])[1])({})", "('str', 'spam2/file1.txt', False)")),
