 ['shutil.copy and shutil.copytree of the chapter: what they return', "import os, shutil, tempfile, zipfile, io, sys\nfrom pathlib import Path\nh = Path(tempfile.mkdtemp())\nos.chdir(h)\ndef rel(x): return str(x).replace(str(h), 'H')\n(h / 'spam').mkdir(exist_ok=True)\nwith open(h / 'spam/file1.txt', 'w', encoding='utf-8') as file:\n    print(file.write('Hello'))\nr = shutil.copy(h / 'spam/file1.txt', h)\nprint(type(r).__name__, rel(r))\nr = shutil.copy(h / 'spam/file1.txt', h / 'spam/file2.txt')\nprint(type(r).__name__, rel(r))\nr = shutil.copytree(h / 'spam', h / 'spam_backup')\nprint(type(r).__name__, rel(r), sorted(p.name for p in r.iterdir()))\ntry:\n    shutil.copytree(h / 'spam', h / 'spam_backup')\nexcept FileExistsError as e:\n    print(type(e).__name__)\nprint(rel(shutil.copytree(h / 'spam', h / 'spam_backup', dirs_exist_ok=True)))\nshutil.rmtree(h)", "5\nstr H/file1.txt\nPosixPath H/spam/file2.txt\nPosixPath H/spam_backup ['file1.txt', 'file2.txt']\nFileExistsError\nH/spam_backup"],
