 ['os.listdir, iterdir and the walk of the chapter with its upper-case renaming', "import os, shutil, tempfile, zipfile, io, sys\nfrom pathlib import Path\nh = Path(tempfile.mkdtemp())\nos.chdir(h)\ndef rel(x): return str(x).replace(str(h), 'H')\nfor d in ('spam', 'spam/eggs', 'spam/eggs2', 'spam/eggs/bacon'):\n    (h / d).mkdir(exist_ok=True)\nfor f in ['spam/file1.txt', 'spam/eggs/file2.txt', 'spam/eggs/file3.txt', 'spam/eggs/bacon/file4.txt']:\n    with open(h / f, 'w', encoding='utf-8') as file:\n        file.write('Hello')\nprint(sorted(os.listdir(h / 'spam')), sorted(p.name for p in (h / 'spam').iterdir()))\nfor folder_name, subfolders, filenames in os.walk(h / 'spam'):\n    subfolders.sort()\n    filenames.sort()\n    print('The current folder is ' + rel(folder_name))\n    for subfolder in subfolders:\n        print('SUBFOLDER OF ' + rel(folder_name) + ': ' + subfolder)\n    for filename in filenames:\n        print('FILE INSIDE ' + rel(folder_name) + ': '+ filename)\n        p = Path(folder_name)\n        shutil.move(p / filename, p / filename.upper())\n    print('')\nprint(sorted(str(p.relative_to(h)) for p in (h / 'spam').rglob('*.TXT')))\nshutil.rmtree(h)", "['eggs', 'eggs2', 'file1.txt'] ['eggs', 'eggs2', 'file1.txt']\nThe current folder is H/spam\nSUBFOLDER OF H/spam: eggs\nSUBFOLDER OF H/spam: eggs2\nFILE INSIDE H/spam: file1.txt\n\nThe current folder is H/spam/eggs\nSUBFOLDER OF H/spam/eggs: bacon\nFILE INSIDE H/spam/eggs: file2.txt\nFILE INSIDE H/spam/eggs: file3.txt\n\nThe current folder is H/spam/eggs/bacon\nFILE INSIDE H/spam/eggs/bacon: file4.txt\n\nThe current folder is H/spam/eggs2\n\n['spam/FILE1.TXT', 'spam/eggs/FILE2.TXT', 'spam/eggs/FILE3.TXT', 'spam/eggs/bacon/FILE4.TXT']"],
 ['os.walk yields strings, can be pruned, and Path.walk yields Paths', "import os, shutil, tempfile, zipfile, io, sys\nfrom pathlib import Path\nh = Path(tempfile.mkdtemp())\nos.chdir(h)\ndef rel(x): return str(x).replace(str(h), 'H')\nfor d in ('spam/eggs/bacon', 'spam/skip'):\n    (h / d).mkdir(parents=True)\n(h / 'spam/file1.txt').write_text('x')\nfirst = next(os.walk(h / 'spam'))\nprint(type(first[0]).__name__, type(first[1]).__name__, type(first[2]).__name__)\nprint(type(next((h / 'spam').walk())[0]).__name__)\nfor root, dirs, files in os.walk(h / 'spam'):\n    if 'skip' in dirs:\n        dirs.remove('skip')\n    print(Path(root).relative_to(h).as_posix(), sorted(dirs))\nprint([Path(a).name for a, b, c in os.walk(h / 'spam', topdown=False) if a != str(h / 'spam')][-1])\nfor root, dirs, files in os.walk(h / 'spam', topdown=False):\n    for name in files:\n        os.remove(os.path.join(root, name))\n    for name in dirs:\n        os.rmdir(os.path.join(root, name))\nos.rmdir(h / 'spam')\nprint((h / 'spam').exists())\nshutil.rmtree(h)", "str list list\nPosixPath\nspam ['eggs']\nspam/eggs ['bacon']\nspam/eggs/bacon []\neggs\nFalse"],
 ['the ZIP listing of the chapter: sizes and the ratio it prints', "import os, shutil, tempfile, zipfile, io, sys\nfrom pathlib import Path\nh = Path(tempfile.mkdtemp())\nos.chdir(h)\ndef rel(x): return str(x).replace(str(h), 'H')\nwith open('file1.txt', 'w', encoding='utf-8') as file_obj:\n    print(file_obj.write('Hello' * 10000))\nwith zipfile.ZipFile('example.zip', 'w') as example_zip:\n    example_zip.write('file1.txt', compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)\nexample_zip = zipfile.ZipFile('example.zip')\nprint(example_zip.namelist())\nfile1_info = example_zip.getinfo('file1.txt')\nprint(file1_info.file_size, file1_info.compress_size)\nprint(f'Compressed file is {round(file1_info.file_size / file1_info.compress_size, 2)}x smaller!')\nexample_zip.close()\nos.chdir('/')\nshutil.rmtree(h)", "50000\n['file1.txt']\n50000 97\nCompressed file is 515.46x smaller!"],
 ["the compression levels and the default method on the chapter's data", "import os, shutil, tempfile, zipfile, io, sys\nfrom pathlib import Path\nh = Path(tempfile.mkdtemp())\nos.chdir(h)\ndef rel(x): return str(x).replace(str(h), 'H')\ndata = 'Hello' * 10000\nfor lvl in (0, 1, 6, 9):\n    b = io.BytesIO()\n    with zipfile.ZipFile(b, 'w') as z:\n        z.writestr('a.txt', data, compress_type=zipfile.ZIP_DEFLATED, compresslevel=lvl)\n    print(lvl, zipfile.ZipFile(b).getinfo('a.txt').compress_size)\nb = io.BytesIO()\nwith zipfile.ZipFile(b, 'w') as z:\n    z.writestr('a.txt', data)\ni = zipfile.ZipFile(b).getinfo('a.txt')\nprint('default', i.compress_type, i.compress_size)\nb = io.BytesIO()\nwith zipfile.ZipFile(b, 'w', zipfile.ZIP_DEFLATED) as z:\n    z.writestr('a.txt', data)\nprint('constructor deflate', zipfile.ZipFile(b).getinfo('a.txt').compress_size)\nprint(zipfile.ZIP_STORED, zipfile.ZIP_DEFLATED, zipfile.ZIP_BZIP2, zipfile.ZIP_LZMA, zipfile.ZIP_ZSTANDARD)\nshutil.rmtree(h)", '0 50010\n1 293\n6 97\n9 97\ndefault 0 50000\nconstructor deflate 97\n0 8 12 14 93'],
 ['extract, extractall, append mode, exclusive mode and a closed archive', "import os, shutil, tempfile, zipfile, io, sys\nfrom pathlib import Path\nh = Path(tempfile.mkdtemp())\nos.chdir(h)\ndef rel(x): return str(x).replace(str(h), 'H')\nwith zipfile.ZipFile('example.zip', 'w') as z:\n    z.writestr('file1.txt', 'Hello')\n    z.writestr('sub/file2.txt', 'Hi')\nexample_zip = zipfile.ZipFile('example.zip')\nprint(rel(example_zip.extract('file1.txt')))\nprint(rel(example_zip.extract('file1.txt', h / 'some' / 'new' / 'folders')))\nexample_zip.extractall(h / 'all')\nprint(sorted(str(p.relative_to(h / 'all')) for p in (h / 'all').rglob('*')))\ntry:\n    example_zip.extract('nothing.txt')\nexcept KeyError as e:\n    print('KeyError', e)\nprint(example_zip.testzip(), zipfile.is_zipfile('example.zip'), zipfile.is_zipfile('file1.txt'))\nexample_zip.close()\ntry:\n    example_zip.read('file1.txt')\nexcept ValueError as e:\n    print('ValueError', e)\nwith zipfile.ZipFile('example.zip', 'a') as z:\n    z.writestr('added.txt', 'more')\nprint(zipfile.ZipFile('example.zip').namelist())\ntry:\n    zipfile.ZipFile('example.zip', 'x')\nexcept FileExistsError:\n    print('FileExistsError')\nwith zipfile.ZipFile('example.zip', 'w') as z:\n    z.writestr('only.txt', 'x')\nprint(zipfile.ZipFile('example.zip').namelist())\nos.chdir('/')\nshutil.rmtree(h)", 'H/file1.txt\nH/some/new/folders/file1.txt\n[\'file1.txt\', \'sub\', \'sub/file2.txt\']\nKeyError "There is no item named \'nothing.txt\' in the archive"\nNone True False\nValueError Attempt to use ZIP archive that was already closed\n[\'file1.txt\', \'sub/file2.txt\', \'added.txt\']\nFileExistsError\n[\'only.txt\']'],
