 ['Project 5 of the chapter, run twice on a small tree', "import os, shutil, tempfile, zipfile, io, sys\nfrom pathlib import Path\nh = Path(tempfile.mkdtemp())\nos.chdir(h)\ndef rel(x): return str(x).replace(str(h), 'H')\n(h / 'spam').mkdir()\n(h / 'spam/file1.txt').write_text('Hello')\ndef backup_to_zip(folder):\n    folder = Path(folder)\n    number = 1\n    while True:\n        zip_filename = Path(folder.parts[-1] + '_' + str(number) + '.zip')\n        if not zip_filename.exists():\n            break\n        number = number + 1\n    print(f'Creating {zip_filename}...')\n    backup_zip = zipfile.ZipFile(zip_filename, 'w')\n    for folder_name, subfolders, filenames in os.walk(folder):\n        folder_name = Path(folder_name)\n        print(f'Adding files in folder {rel(folder_name)}...')\n        for filename in filenames:\n            print(f'Adding file {filename}...')\n            backup_zip.write(folder_name / filename)\n    backup_zip.close()\n    print('Done.')\nbackup_to_zip(h / 'spam')\nbackup_to_zip(h / 'spam')\nnames = zipfile.ZipFile('spam_2.zip').namelist()\nprint(len(names), names[0] == str(h / 'spam/file1.txt').lstrip('/'), names[0].endswith('spam/file1.txt'))\nprint(sorted(p.name for p in h.glob('*.zip')))\ninfo = zipfile.ZipFile('spam_1.zip').getinfo(names[0])\nprint(info.compress_type, info.file_size, info.compress_size)\nos.chdir('/')\nshutil.rmtree(h)", "Creating spam_1.zip...\nAdding files in folder H/spam...\nAdding file file1.txt...\nDone.\nCreating spam_2.zip...\nAdding files in folder H/spam...\nAdding file file1.txt...\nDone.\n1 True True\n['spam_1.zip', 'spam_2.zip']\n0 5 5"],
 ['Project 5 fails for a folder given as a dot and adds the archive to itself', "import os, shutil, tempfile, zipfile, io, sys\nfrom pathlib import Path\nh = Path(tempfile.mkdtemp())\nos.chdir(h)\ndef rel(x): return str(x).replace(str(h), 'H')\n(h / 'spam').mkdir()\n(h / 'spam/file1.txt').write_text('Hello')\nprint(Path('.').parts)\ntry:\n    Path('.').parts[-1]\nexcept IndexError as e:\n    print(type(e).__name__, e)\nos.chdir(h / 'spam')\nz = zipfile.ZipFile('spam_1.zip', 'w')\nadded = []\nfor folder_name, subfolders, filenames in os.walk(h / 'spam'):\n    for filename in sorted(filenames):\n        added.append(filename)\n        z.write(Path(folder_name) / filename)\nz.close()\nprint(added)\nos.chdir('/')\nshutil.rmtree(h)", "()\nIndexError tuple index out of range\n['file1.txt', 'spam_1.zip']"],
 ['shutil.make_archive and shutil.unpack_archive', "import os, shutil, tempfile, zipfile, io, sys\nfrom pathlib import Path\nh = Path(tempfile.mkdtemp())\nos.chdir(h)\ndef rel(x): return str(x).replace(str(h), 'H')\n(h / 'spam/sub').mkdir(parents=True)\n(h / 'spam/a.txt').write_text('Hello' * 100)\n(h / 'spam/sub/b.txt').write_text('B')\nname = shutil.make_archive(str(h / 'snap'), 'zip', root_dir=h, base_dir='spam')\nprint(rel(name))\nzf = zipfile.ZipFile(name)\nprint(sorted(zf.namelist()), sorted({i.compress_type for i in zf.infolist()}))\nshutil.unpack_archive(name, h / 'un')\nprint(sorted(str(p.relative_to(h / 'un')) for p in (h / 'un').rglob('*')))\nprint(sorted(f for f, d in shutil.get_archive_formats()))\nos.chdir('/')\nshutil.rmtree(h)", "H/snap.zip\n['spam/', 'spam/a.txt', 'spam/sub/', 'spam/sub/b.txt'] [0, 8]\n['spam', 'spam/a.txt', 'spam/sub', 'spam/sub/b.txt']\n['bztar', 'gztar', 'tar', 'xztar', 'zip', 'zstdtar']"],
 ['pathlib in 3.14 copies and moves, and a Path walks itself', "import os, shutil, tempfile, zipfile, io, sys\nfrom pathlib import Path\nh = Path(tempfile.mkdtemp())\nos.chdir(h)\ndef rel(x): return str(x).replace(str(h), 'H')\nimport pathlib\nprint([hasattr(pathlib.Path, m) for m in ('copy', 'copy_into', 'move', 'move_into', 'walk')])\n(h / 'a.txt').write_text('A')\n(h / 'box').mkdir()\np = (h / 'a.txt').copy(h / 'b.txt')\nprint(type(p).__name__, p.name, (h / 'a.txt').exists())\np = (h / 'b.txt').move(h / 'c.txt')\nprint(p.name, (h / 'b.txt').exists())\nprint(rel((h / 'c.txt').copy_into(h / 'box')), rel((h / 'a.txt').move_into(h / 'box')))\nprint(sorted(x.name for x in (h / 'box').iterdir()), (h / 'a.txt').exists())\nos.chdir('/')\nshutil.rmtree(h)", "[True, True, True, True, True]\nPosixPath b.txt True\nc.txt False\nH/box/c.txt H/box/a.txt\n['a.txt', 'c.txt'] False"],
