 ['practice programs 1 to 4 of the chapter as solutions written for this study', "import os, shutil, tempfile, zipfile, io, sys\nfrom pathlib import Path\nh = Path(tempfile.mkdtemp())\nos.chdir(h)\ndef rel(x): return str(x).replace(str(h), 'H')\nimport re\nfor d in ('src/a', 'src/b'):\n    (h / d).mkdir(parents=True)\nfor f in ('src/one.pdf', 'src/a/two.PDF', 'src/b/three.txt', 'src/b/four.pdf'):\n    (h / f).write_text(f)\n(h / 'dest').mkdir()\nfor folder_name, subfolders, filenames in os.walk(h / 'src'):\n    for filename in filenames:\n        if filename.lower().endswith('.pdf'):\n            shutil.copy(Path(folder_name) / filename, h / 'dest')\nprint(sorted(p.name for p in (h / 'dest').iterdir()))\nMB = 1024 * 1024\n(h / 'big').mkdir()\nwith open(h / 'big/huge.bin', 'wb') as f:\n    f.truncate(100 * MB + 1)\nwith open(h / 'big/exact.bin', 'wb') as f:\n    f.truncate(100 * MB)\nfor folder_name, subfolders, filenames in os.walk(h / 'big'):\n    for filename in filenames:\n        path = os.path.join(folder_name, filename)\n        if os.path.getsize(path) > 100 * MB:\n            print(rel(path), os.path.getsize(path))\nnum = Path('nums')\nnum.mkdir()\nfor i in range(1, 121):\n    if i not in (42, 86, 103):\n        with open(num / f'spam{str(i).zfill(3)}.txt', 'w') as file:\n            pass\nfiles = sorted(num.glob('spam*.txt'))\nprint(len(files))\nfor new_number, p in enumerate(files, start=1):\n    new_name = f'spam{str(new_number).zfill(3)}.txt'\n    if p.name != new_name:\n        shutil.move(p, p.with_name(new_name))\nnames = sorted(p.name for p in num.iterdir())\nprint(len(names), names[0], names[-1], names[41], names == [f'spam{str(i).zfill(3)}.txt' for i in range(1, 118)])\ndates = Path('dates')\ndates.mkdir()\nfor n in ('spam12-31-1900.txt', 'report01-02-2020.txt', 'notes.txt'):\n    (dates / n).write_text('')\npattern = re.compile(r'(\\d\\d)-(\\d\\d)-(\\d\\d\\d\\d)')\nfor folder_name, subfolders, filenames in os.walk(dates):\n    for filename in filenames:\n        if pattern.search(filename):\n            shutil.move(Path(folder_name) / filename, Path(folder_name) / pattern.sub(r'\\2-\\1-\\3', filename))\nprint(sorted(p.name for p in dates.iterdir()))\nos.chdir('/')\nshutil.rmtree(h)", "['four.pdf', 'one.pdf', 'two.PDF']\nH/big/huge.bin 104857601\n117\n117 spam001.txt spam117.txt spam042.txt True\n['notes.txt', 'report02-01-2020.txt', 'spam31-12-1900.txt']"],
